#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
game_result simulate_game(const unsigned char *a, size_t na, const unsigned char *b,
                          size_t nb) {
    size_t total = na + nb, counts[2] = {na, nb};
    unsigned char *hands[2] = {(unsigned char *)malloc(total + 1),
                               (unsigned char *)malloc(total + 1)},
                  *pile = (unsigned char *)malloc(total + 1);
    if (na)
        memcpy(hands[0], a, na);
    if (nb)
        memcpy(hands[1], b, nb);
    unsigned char **seen = NULL;
    size_t ns = 0, np = 0;
    int turn = 0, debt = 0;
    game_result result = {false, 0, 0};
    for (;;) {
        if (!np) {
            unsigned char *state = (unsigned char *)malloc(total + 1 + sizeof(size_t));
            state[0] = (unsigned char)turn;
            memcpy(state + 1, &counts[0], sizeof(size_t));
            memcpy(state + 1 + sizeof(size_t), hands[0], counts[0]);
            memcpy(state + 1 + sizeof(size_t) + counts[0], hands[1], counts[1]);
            bool repeat = false;
            for (size_t i = 0; i < ns; i++)
                if (!memcmp(seen[i], state, total + 1 + sizeof(size_t))) {
                    repeat = true;
                    break;
                }
            if (repeat) {
                free(state);
                result.loop = true;
                break;
            }
            seen = (unsigned char **)realloc(seen, (ns + 1) * sizeof(unsigned char *));
            seen[ns++] = state;
        }
        if (!counts[turn]) {
            result.tricks += np ? 1 : 0;
            break;
        }
        unsigned char c = hands[turn][0];
        memmove(hands[turn], hands[turn] + 1, --counts[turn]);
        pile[np++] = c;
        result.cards++;
        if (c) {
            debt = c;
            turn = 1 - turn;
        } else if (debt) {
            if (!--debt) {
                int winner = 1 - turn;
                memcpy(hands[winner] + counts[winner], pile, np);
                counts[winner] += np;
                np = 0;
                result.tricks++;
                if (!counts[0] || !counts[1])
                    break;
                turn = winner;
            }
        } else
            turn = 1 - turn;
    }
    for (size_t i = 0; i < ns; i++)
        free(seen[i]);
    free(seen);
    free(hands[0]);
    free(hands[1]);
    free(pile);
    return result;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    unsigned char a[] = {0, 4, 0, 0, 2, 0}, b[] = {0, 0, 0, 0, 3, 0, 1};
    game_result r = simulate_game(a, 6, b, 7);
    assert(!r.loop && r.cards == 13 && r.tricks == 1);
    unsigned char c[] = {1, 0, 0}, d[] = {0, 1, 0};
    r = simulate_game(c, 3, d, 3);
    assert(r.loop && r.cards == 8 && r.tricks == 3);
    r = simulate_game(NULL, 0, d, 3);
    assert(!r.loop && r.cards == 0 && r.tricks == 0);

    return 0;
}
